function hgRootSort(roots){
  var pri=[],last=[];
  for(var i=0;i<roots.length;i++){
    var r=roots[i];
    if(r.indexOf('arj2ftl0')>=0||r.indexOf('40ygo615')>=0||r.indexOf('h2na6qa39')>=0||r.indexOf('jxqgmx5ga')>=0)last.push(r);
