      var pr=[];
      while((mm=re.exec(m[1]))!=null)pr.push(mm[1].replace(/\/+$/,''));
      if(pr.length)roots=pr;
    }
  }
  roots=hgRootSort(roots);
  var cs=[];
  for(var i=0;i<roots.length;i++)for(var j=0;j<hgSubs().length;j++)cs.push('https://'+hgSubs()[j]+'.'+roots[i]);
  cs.push(hgDef());
  var seen={},ls=[];
  for(var m2=0;m2<cs.length;m2++){if(!seen[cs[m2]]){seen[cs[m2]]=1;ls.push(cs[m2])}}
  return ls}
function hgBatchProbe(urls){
  var rows=[];
  var res=null;
  try{res=java.ajaxAll(urls,true)}catch(e1){if(urls&&urls.length===1){}else{try{res=java.ajaxAll(urls)}catch(e2){}}}
  if(!res&&urls&&urls.length===1){
    try{var b=String(java.ajax(urls[0]+',{"timeout":8000,"retry":0}'));if(b.length>20000&&b.indexOf('Exception')<0)rows.push({url:urls[0],host:hgHost(urls[0]),ms:0,fin:''})}catch(e3){}
    return rows}
  if(res){
    for(var k=0;k<res.length;k++){
      var code=-9,ms=-1,bl=0,fin='',bod='';
      try{code=res[k].raw().code()}catch(e){}
      try{ms=res[k].callTime()}catch(e){}
